import java.util.*;

// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    static double brute(int[] a, int[] b) {
        int[] c = new int[a.length + b.length];
        System.arraycopy(a, 0, c, 0, a.length);
        System.arraycopy(b, 0, c, a.length, b.length);
        Arrays.sort(c);
        int k = c.length;
        return k % 2 == 1 ? c[k / 2] : ((long) c[k / 2 - 1] + c[k / 2]) / 2.0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("RUN")) {
                    r = String.valueOf(Median.median(arr(p[1]), arr(p[2])));
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(15);
                    String sai = null;
                    int done = 0;
                    for (int t = 0; t < 5000 && sai == null; t++) {
                        int[] a = new int[rnd.nextInt(7)], b = new int[rnd.nextInt(7)];
                        if (a.length + b.length == 0) {
                            continue;
                        }
                        for (int i = 0; i < a.length; i++) {
                            a[i] = rnd.nextInt(21) - 10;
                        }
                        for (int i = 0; i < b.length; i++) {
                            b[i] = rnd.nextInt(21) - 10;
                        }
                        Arrays.sort(a);
                        Arrays.sort(b);
                        done++;
                        double got = Median.median(a.clone(), b.clone()), want = brute(a, b);
                        if (got != want) {
                            sai = str(a) + " + " + str(b) + " -> " + got + ", expected " + want;
                        }
                    }
                    r = ketQua("random pairs (one empty, duplicates, negatives)", done, sai);
                } else {
                    final int[] a = new int[1000000], b = new int[1000001];
                    for (int i = 0; i < a.length; i++) {
                        a[i] = 2 * i;
                    }
                    for (int i = 0; i < b.length; i++) {
                        b[i] = 3 * i - 7;
                    }
                    final double[] s = new double[1];
                    r = Kiem.hen("300,000 calls on 1,000,000 + 1,000,001 elements", 3000, new Runnable() {
                        public void run() {
