                                s[0] += i % 2 == 0 ? Median.median(a, b) : Median.median(b, a);
                            }
                        }
                    }) + ", sum " + s[0];
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
